const values = /%[sqvd]/g
const escapeRegex = (value: string) => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
const compile = (template: string) => new RegExp(`^${template.split(values).map(escapeRegex).join('([\\s\\S]*?)')}$`)
const directions = {
  en: messages.map(([vi, en]) => ({ from: vi, to: en })),
  vi: messages.map(([vi, en]) => ({ from: en, to: vi })),
}
const catalogs = Object.fromEntries(Object.entries(directions).map(([lang, entries]) => [lang, {
  exact: new Map(entries.filter(entry => !entry.from.match(values)).map(entry => [entry.from, entry.to])),
  templates: entries.filter(entry => entry.from.match(values)).map(entry => ({ pattern: compile(entry.from), to: entry.to })),
}])) as Record<Lang, { exact: Map<string, string>; templates: { pattern: RegExp; to: string }[] }>

export function savedLanguage(): Lang {
  return localStorage.getItem('language') === 'en' ? 'en' : 'vi'
}

export function localizeMessage(message: string, lang: Lang): string {
  const catalog = catalogs[lang]
  const exact = catalog.exact.get(message)
  if (exact !== undefined) return exact
  for (const template of catalog.templates) {
    const match = template.pattern.exec(message)
    if (match) {
      let index = 0
      return template.to.replace(values, () => match[++index])
    }
  }
  return message
}
